package com.careerpilot.backend.modules.application.services;
import com.careerpilot.backend.modules.application.domain.*; import org.springframework.stereotype.Service;
@Service public class ApprovalPolicyEngine { public record Context(double matchScore,boolean remote,String technology,String location){} public boolean shouldAutoApprove(ApprovalPolicy p,Context c){if(p==null||p.getMode()!=ApprovalMode.POLICY_BASED)return false;if(p.getMinimumScore()!=null&&c.matchScore()<p.getMinimumScore())return false;if(Boolean.TRUE.equals(p.getRequireRemote())&&!c.remote())return false;if(p.getTechnology()!=null&&!p.getTechnology().equalsIgnoreCase(c.technology()))return false;return p.getLocation()==null||p.getLocation().equalsIgnoreCase(c.location());} public WorkflowState nextState(ApprovalPolicy p,Context c){return shouldAutoApprove(p,c)?WorkflowState.APPROVED:WorkflowState.WAITING_APPROVAL;} }
